 for id in ids.split():
  assert id in units
  records.append(dict(unit_id=id,identification=identification,cognitive=cognitive,elaboration=elaboration,social=social,binding=binding,scope=scope,confidence=confidence,basic_meaning=basic,contextual_meaning=context,evidence=evidence or f"{units[id]['word']}: {context}; compared with {basic}"))
